import json
import itertools

def main():
    houses = ["1", "2"]
    names = ["Eric", "Arnold"]
    foods = ["pizza", "grilled cheese"]

    solution = None
    for names_perm in itertools.permutations(names):
        for foods_perm in itertools.permutations(foods):
            # Clue 1: The person who is a pizza lover is in the second house.
            if foods_perm[1] != "pizza":
                continue
            # Clue 2: Arnold is not in the first house.
            if names_perm[0] == "Arnold":
                continue
            # Build assignment for the houses.
            current_solution = [
                [houses[0], names_perm[0], foods_perm[0]],
                [houses[1], names_perm[1], foods_perm[1]]
            ]
            solution = current_solution
            break
        if solution is not None:
            break

    output = {
        "solution": {
            "header": ["House", "Name", "Food"],
            "rows": solution
        }
    }
    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
